


export type UpdatePackageRequestInput = { /** Controls buyer email handling. Omit or use send to send when recipient, template, and deduplication rules allow it. Use suppress when another system owns buyer messaging. */ "buyer_notification_behavior"?: "send" | "suppress"; "carrier"?: string | null; "dimensions"?: (({ "height": number; "length": number; "unit": string; "width": number; }) | (null)); /** Optional resource version last read by the caller. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "expected_version"?: string; /** Caller-owned identifier for this resource in an external system. Caller-owned package identifier in external_system. Set with external_system to enable duplicate detection and replay for that provider reference. minLength: 1. maxLength: 255. */ "external_reference_id"?: string | null; /** External carrier, aggregator, or fulfillment platform name for this package. Set with external_reference_id to enable duplicate detection and replay for that provider reference; without external_reference_id this is stored as provenance only. */ "external_system"?: string | null; /** Merchant or integration supplied HTTPS shipping-label URL for authenticated merchant workflows. Non-Flint URLs must include external_system for provenance. Flint does not currently manage label file hosting or buyer-facing label downloads. */ "label_url"?: string | null; /** Caller-owned metadata. Omit this field to leave metadata unchanged. Send an object to merge by key, set a key to null to remove it, or set metadata to null to clear all metadata. An empty object makes no change. Empty strings are stored. Keys starting with flint_ are reserved and cannot be written through the public API. */ "metadata"?: Record<string, string | null> | null; "service_code"?: string | null; "status_reason"?: string | null; "tracking_number"?: string | null; /** Absolute HTTPS carrier tracking URL. Embedded URL credentials are rejected. */ "tracking_url"?: string | null; "weight"?: (({ /** Weight unit. Use gram, kilogram, ounce, or pound. */ "unit": "gram" | "kilogram" | "ounce" | "pound"; "value": number; }) | (null)); };
